// UpdateIntent is the resolver for the updateIntent field.
func (r *mutationResolver) UpdateIntent(ctx context.Context, id string, input model.UpdateIntentInput) (*model.Intent, error) {
	uid, err := requireUser(ctx)
	if err != nil {
		return nil, err
	}
	iid, _ := strconv.ParseInt(id, 10, 64)
	if input.ScheduleTimezone != nil {
		return nil, fmt.Errorf("scheduleTimezone is not supported by the shared database schema")
	}

	// Build dynamic update
	setClauses := []string{}
	args := []any{}

	if input.Name != nil {
		setClauses = append(setClauses, "name = ?")
		args = append(args, *input.Name)
	}
	if input.Description != nil {
		setClauses = append(setClauses, "description = ?")
		args = append(args, *input.Description)
	}
	if input.Enabled != nil {
		v := 0
		if *input.Enabled {
			v = 1
		}
		setClauses = append(setClauses, "enabled = ?")
		args = append(args, v)
	}
	appendArray := func(column string, values []string) {
		if values == nil {
			return
		}
		encoded, _ := json.Marshal(values)
		setClauses = append(setClauses, column+" = ?")
		args = append(args, string(encoded))
	}
	appendArray("match_containers", input.MatchContainers)
	appendArray("match_images", input.MatchImages)
	appendArray("match_sources", input.MatchSources)
	appendArray("match_stacks", input.MatchStacks)
	appendArray("match_registries", input.MatchRegistries)
	appendArray("exclude_containers", input.ExcludeContainers)
	appendArray("exclude_images", input.ExcludeImages)
	appendArray("exclude_stacks", input.ExcludeStacks)
	appendArray("exclude_registries", input.ExcludeRegistries)
	if input.ScheduleType != nil {
		setClauses = append(setClauses, "schedule_type = ?")
		args = append(args, dbEnumValue(string(*input.ScheduleType)))
	}
	if input.ScheduleCron != nil {
		setClauses = append(setClauses, "schedule_cron = ?")
		args = append(args, *input.ScheduleCron)
	}
	if input.MaxConcurrent != nil {
		setClauses = append(setClauses, "max_concurrent = ?")
		args = append(args, *input.MaxConcurrent)
	}
	if input.DryRun != nil {
		v := 0
		if *input.DryRun {
			v = 1
		}
		setClauses = append(setClauses, "dry_run = ?")
		args = append(args, v)
	}
	if input.SequentialDelaySec != nil {
		setClauses = append(setClauses, "sequential_delay_sec = ?")
		args = append(args, *input.SequentialDelaySec)
	}

	if len(setClauses) > 0 {
		setClauses = append(setClauses, "updated_at = datetime('now')")
		args = append(args, iid, uid)
		query := fmt.Sprintf("UPDATE intents SET %s WHERE id = ? AND user_id = ?", joinStr(setClauses, ", "))
		if _, err := r.DB.ExecContext(ctx, query, args...); err != nil {
			return nil, err
		}
	}

	row, _ := db.GetIntentByID(ctx, r.DB, iid, uid)
	if row == nil {
		return nil, fmt.Errorf("not found")
	}
	return intentToModel(row), nil
}

